mapper.select:
select id, events, category, name, phone, occur_time, solve_time, address, longitude, latitude, ST_AsText(geom) as geom
from sum_12345_wash

    ST_AsText(geom)!=''

        and id = #{condition.id}


        and category = #{condition.category}


        and name = #{condition.name}


        and phone = #{condition.phone}


        and occur_time > #{condition.occur_time}


        and solve_time < #{condition.solve_time}


        and address like concat('%',#{condition.address},'%')
